{
  "paper_title": "Some Methods for Classification and Analysis of Multivariate Observations",
  "authors_year": "J. MacQueen, 1967",
  "research_question": "How can an N-dimensional population be efficiently partitioned into k sets (k-means) based on a sample, and what is the asymptotic behavior of such a partitioning process?",
  "context": "The work originates from problems in optimal information structures and optimal classification, desiring a computationally feasible method to partition data into similarity groups or clusters with low within-class variance.",
  "methods": [
    "k-means sequential partitioning procedure",
    "Martingale theory and convergence proofs",
    "Coarsening and refining heuristic parameters C and R",
    "Fitting joint normal mixtures for distribution approximation",
    "Scrambled dimension test for independence",
    "Two-step improvement procedure"
  ],
  "main_findings": [
    "The sequence of random variables representing expected within-class variance W(xn) converges almost surely to V(x) for some unbiased k-point x.",
    "The k-means procedure is computationally economical and feasible for processing very large samples on digital computers.",
    "The k-means process can be effectively adapted for similarity grouping, relevant classification/prediction, distribution approximation, and tests for independence."
  ],
  "assumptions": [
    "The probability measure p is absolutely continuous with respect to Lebesgue measure on EN.",
    "p(R) = 1 for a closed and bounded convex set R subset of EN, and p(A) > 0 for every open set A subset of R."
  ],
  "limitations_explicit": [
    "In general, the k-means procedure will not converge to an optimal partition.",
    "There is no feasible, general method which always yields an optimal partition."
  ],
  "potential_open_questions": [
    {
      "question": "Can the theoretical convergence guarantees be strengthened to eliminate the possibility of the means slowly and indefinitely oscillating around the center in certain symmetric configurations?",
      "why_unresolved": "Theorem 1 establishes almost sure convergence but does not fully eliminate slow oscillations in specific symmetric cases like a uniform distribution over a disk.",
      "evidence": "Theorem 1 provides for a.s. convergence of the sum, but theorem 1 does not quite permit us to eliminate the interesting possibility that the two means oscillate slowly but indefinitely around the center.",
      "sections": [
        "Section 2.3"
      ]
    },
    {
      "question": "What is the precise statistical power of the proposed scrambled dimension test for independence across various types of underlying data distributions and sample sizes?",
      "why_unresolved": "A computer program was not available to do the scrambling due to the inconvenience of punched cards, leaving further testing and power evaluation unundertaken.",
      "evidence": "A computer program was not available to do the scrambling, and its being inconvenient to set up large numbers of scrambled samples using punched cards, further testing of this method was not undertaken.",
      "sections": [
        "Section 3.4"
      ]
    }
  ],
  "candidate_hypotheses": [
    {
      "hypothesis": "For fixed marginal distributions, the within-class variance for the optimal partition is maximal when the joint distribution is actually the product of the marginals.",
      "rationale": "Intuition and examination of scrambled versus unscrambled variances suggest that destroying independence by scrambling systematically increases within-class variance.",
      "evidence": "On the encouraging side is the related conjecture, that for fixed marginal distributions, the within-class variance for the optimal partition as defined in section 1 is maximal when the joint distribution is actually the product of the marginals.",
      "sections": [
        "Section 3.4"
      ]
    },
    {
      "hypothesis": "Under independent sampling in general compact metric spaces, the sequence of sample k-centroids will converge almost surely, with convergent subsequences having their limits in the class of unbiased k-points.",
      "rationale": "The extension of the k-means concept using metric centroids parallels the Euclidean proofs relying on compactness and uniform boundedness.",
      "evidence": "It would seem reasonable to suppose that the obvious extension of theorem 1 would hold. That is, under independent sampling, sum of integrals of distance functions will converge a.s., and convergent subsequences... will have their limits in the class of unbiased k-points.",
      "sections": [
        "Section 4"
      ]
    }
  ]
}

{
 "paper_title":"TRIMMED k-MEANS: AN ATTEMPT TO ROBUSTIFY QUANTIZERS",
 "authors_year":"J. A. Cuesta-Albertos, A. Gordaliza and C. Matran, 1997",
 "research_question":"How to design robustified k-means clustering procedures using impartial trimming and establish their existence and strong consistency?",
 "context":"Clustering and quantization of random variables where standard methods lack robustness or rely on arbitrary trimming zones.",
 "methods":[
  "Using impartial trimming functions based on data joint structure",
  "Minimizing penalized variation over k-sets and trimming functions",
  "Simulated annealing based algorithms for practical optimization"
 ],
 "main_findings":[
  "Existence of trimmed k-means under general conditions",
  "Optimal trimming functions essentially coincide with indicator functions of unions of k balls of the same radius",
  "Strong consistency of empirical trimmed k-means to population counterparts under continuity assumptions"
 ],
 "assumptions":[
  "The penalty function Phi is continuous, nondecreasing, with Phi(0)=0 and Phi(x) < infinity",
  "Probability measure PX is continuous for consistency theorems"
 ],
 "limitations_explicit":[
  "Nonexistence of a deterministic optimal algorithm to choose the optimal trimming set",
  "Breakdown point can be low depending on the data structure and relative cluster proportions"
 ],
 "potential_open_questions":[
  {
   "question":"How does the breakdown point of trimmed k-means behave generally across arbitrary probability distributions and contamination types?",
   "why_unresolved":"The breakdown point depends heavily on the specific configuration of clusters and data probabilities.",
   "evidence":"Section 5 demonstrates examples where the breakdown point of the alpha-trimmed k-mean can be as close to 0 as desired.",
   "sections":[
    "Section 5"
   ]
  }
 ],
 "candidate_hypotheses":[
